import sys

def solve():
    try:
        line = sys.stdin.readline()
        if not line:
            return
        n = int(line.strip())
    except ValueError:
        return

    # Grid to store the color placed at each cell. 0 means empty.
    grid = [[0] * (n + 1) for _ in range(n + 1)]

    # Total number of turns
    total_turns = n * n

    for _ in range(total_turns):
        try:
            line = sys.stdin.readline()
            if not line:
                break
            a = int(line.strip())
        except ValueError:
            break

        # Find an empty cell
        found = False
        for r in range(1, n + 1):
            if found:
                break
            for c in range(1, n + 1):
                if grid[r][c] == 0:
                    # Check neighbors to determine valid colors
                    neighbors_colors = set()

                    # Up
                    if r > 1 and grid[r-1][c] != 0:
                        neighbors_colors.add(grid[r-1][c])
                    # Down
                    if r < n and grid[r+1][c] != 0:
                        neighbors_colors.add(grid[r+1][c])
                    # Left
                    if c > 1 and grid[r][c-1] != 0:
                        neighbors_colors.add(grid[r][c-1])
                    # Right
                    if c < n and grid[r][c+1] != 0:
                        neighbors_colors.add(grid[r][c+1])

                    # Available colors are {1, 2, 3} excluding 'a' and neighbor colors
                    available = []
                    for color in [1, 2, 3]:
                        if color != a and color not in neighbors_colors:
                            available.append(color)

                    if available:
                        b = available[0]
                        grid[r][c] = b
                        print(f"{b} {r} {c}")
                        sys.stdout.flush()
                        found = True
                        break

        if not found:
            # This should theoretically not happen given the problem statement guarantees a win
            break

if __name__ == "__main__":
    solve()
